begin;
-- M2 coordinated cutover: legacy binder revoked from every API role (legacy is owned by postgres, so postgres can revoke it).
revoke execute on function public.bind_research_membership_subscription(uuid,text,text,text,text,public.subscription_billing_interval,timestamptz,jsonb) from service_role, public, anon, authenticated;
do $leg$ declare r text; begin foreach r in array array['service_role','anon','authenticated','authenticator'] loop
  if has_function_privilege(r,'public.bind_research_membership_subscription(uuid,text,text,text,text,public.subscription_billing_interval,timestamptz,jsonb)','EXECUTE') then raise exception 'legacy binder still executable by %',r; end if; end loop;
  if exists(select 1 from aclexplode((select proacl from pg_proc where oid='public.bind_research_membership_subscription(uuid,text,text,text,text,public.subscription_billing_interval,timestamptz,jsonb)'::regprocedure)) x where x.grantee=0) then raise exception 'legacy binder executable by PUBLIC'; end if;
end $leg$;
do $assert$ begin
 if has_function_privilege('anon','public.issue_research_membership_checkout_intent(uuid,text,text,text,text,boolean,text)','EXECUTE') is distinct from false then raise exception 'ACL matrix violation: anon EXECUTE issue expected false'; end if;
 if has_function_privilege('anon','public.attach_research_membership_checkout_intent(uuid,text,text)','EXECUTE') is distinct from false then raise exception 'ACL matrix violation: anon EXECUTE attach expected false'; end if;
 if has_function_privilege('anon','public.observe_signed_research_subscription_created(text,text,text,text,text,text,boolean,timestamptz,text,uuid,text,text,text)','EXECUTE') is distinct from false then raise exception 'ACL matrix violation: anon EXECUTE observe expected false'; end if;
 if has_function_privilege('anon','public.bind_research_membership_with_checkout_intent(uuid,text,text,text,text,text,timestamptz,text,text,text,text,boolean,text,text)','EXECUTE') is distinct from false then raise exception 'ACL matrix violation: anon EXECUTE bind expected false'; end if;
 if has_function_privilege('anon','research_checkout_guard.hold_binding_conflict(uuid,text,text)','EXECUTE') is distinct from false then raise exception 'ACL matrix violation: anon EXECUTE hold expected false'; end if;
 if has_function_privilege('authenticated','public.issue_research_membership_checkout_intent(uuid,text,text,text,text,boolean,text)','EXECUTE') is distinct from false then raise exception 'ACL matrix violation: authenticated EXECUTE issue expected false'; end if;
 if has_function_privilege('authenticated','public.attach_research_membership_checkout_intent(uuid,text,text)','EXECUTE') is distinct from false then raise exception 'ACL matrix violation: authenticated EXECUTE attach expected false'; end if;
 if has_function_privilege('authenticated','public.observe_signed_research_subscription_created(text,text,text,text,text,text,boolean,timestamptz,text,uuid,text,text,text)','EXECUTE') is distinct from false then raise exception 'ACL matrix violation: authenticated EXECUTE observe expected false'; end if;
 if has_function_privilege('authenticated','public.bind_research_membership_with_checkout_intent(uuid,text,text,text,text,text,timestamptz,text,text,text,text,boolean,text,text)','EXECUTE') is distinct from false then raise exception 'ACL matrix violation: authenticated EXECUTE bind expected false'; end if;
 if has_function_privilege('authenticated','research_checkout_guard.hold_binding_conflict(uuid,text,text)','EXECUTE') is distinct from false then raise exception 'ACL matrix violation: authenticated EXECUTE hold expected false'; end if;
 if has_function_privilege('service_role','public.issue_research_membership_checkout_intent(uuid,text,text,text,text,boolean,text)','EXECUTE') is distinct from false then raise exception 'ACL matrix violation: service_role EXECUTE issue expected false'; end if;
 if has_function_privilege('service_role','public.attach_research_membership_checkout_intent(uuid,text,text)','EXECUTE') is distinct from false then raise exception 'ACL matrix violation: service_role EXECUTE attach expected false'; end if;
 if has_function_privilege('service_role','public.observe_signed_research_subscription_created(text,text,text,text,text,text,boolean,timestamptz,text,uuid,text,text,text)','EXECUTE') is distinct from false then raise exception 'ACL matrix violation: service_role EXECUTE observe expected false'; end if;
 if has_function_privilege('service_role','public.bind_research_membership_with_checkout_intent(uuid,text,text,text,text,text,timestamptz,text,text,text,text,boolean,text,text)','EXECUTE') is distinct from false then raise exception 'ACL matrix violation: service_role EXECUTE bind expected false'; end if;
 if has_function_privilege('service_role','research_checkout_guard.hold_binding_conflict(uuid,text,text)','EXECUTE') is distinct from false then raise exception 'ACL matrix violation: service_role EXECUTE hold expected false'; end if;
 if has_function_privilege('authenticator','public.issue_research_membership_checkout_intent(uuid,text,text,text,text,boolean,text)','EXECUTE') is distinct from false then raise exception 'ACL matrix violation: authenticator EXECUTE issue expected false'; end if;
 if has_function_privilege('authenticator','public.attach_research_membership_checkout_intent(uuid,text,text)','EXECUTE') is distinct from false then raise exception 'ACL matrix violation: authenticator EXECUTE attach expected false'; end if;
 if has_function_privilege('authenticator','public.observe_signed_research_subscription_created(text,text,text,text,text,text,boolean,timestamptz,text,uuid,text,text,text)','EXECUTE') is distinct from false then raise exception 'ACL matrix violation: authenticator EXECUTE observe expected false'; end if;
 if has_function_privilege('authenticator','public.bind_research_membership_with_checkout_intent(uuid,text,text,text,text,text,timestamptz,text,text,text,text,boolean,text,text)','EXECUTE') is distinct from false then raise exception 'ACL matrix violation: authenticator EXECUTE bind expected false'; end if;
 if has_function_privilege('authenticator','research_checkout_guard.hold_binding_conflict(uuid,text,text)','EXECUTE') is distinct from false then raise exception 'ACL matrix violation: authenticator EXECUTE hold expected false'; end if;
 if has_function_privilege('review_checkout_issuer','public.issue_research_membership_checkout_intent(uuid,text,text,text,text,boolean,text)','EXECUTE') is distinct from true then raise exception 'ACL matrix violation: review_checkout_issuer EXECUTE issue expected true'; end if;
 if has_function_privilege('review_checkout_issuer','public.attach_research_membership_checkout_intent(uuid,text,text)','EXECUTE') is distinct from true then raise exception 'ACL matrix violation: review_checkout_issuer EXECUTE attach expected true'; end if;
 if has_function_privilege('review_checkout_issuer','public.observe_signed_research_subscription_created(text,text,text,text,text,text,boolean,timestamptz,text,uuid,text,text,text)','EXECUTE') is distinct from false then raise exception 'ACL matrix violation: review_checkout_issuer EXECUTE observe expected false'; end if;
 if has_function_privilege('review_checkout_issuer','public.bind_research_membership_with_checkout_intent(uuid,text,text,text,text,text,timestamptz,text,text,text,text,boolean,text,text)','EXECUTE') is distinct from false then raise exception 'ACL matrix violation: review_checkout_issuer EXECUTE bind expected false'; end if;
 if has_function_privilege('review_checkout_issuer','research_checkout_guard.hold_binding_conflict(uuid,text,text)','EXECUTE') is distinct from false then raise exception 'ACL matrix violation: review_checkout_issuer EXECUTE hold expected false'; end if;
 if has_function_privilege('review_checkout_verifier','public.issue_research_membership_checkout_intent(uuid,text,text,text,text,boolean,text)','EXECUTE') is distinct from false then raise exception 'ACL matrix violation: review_checkout_verifier EXECUTE issue expected false'; end if;
 if has_function_privilege('review_checkout_verifier','public.attach_research_membership_checkout_intent(uuid,text,text)','EXECUTE') is distinct from false then raise exception 'ACL matrix violation: review_checkout_verifier EXECUTE attach expected false'; end if;
 if has_function_privilege('review_checkout_verifier','public.observe_signed_research_subscription_created(text,text,text,text,text,text,boolean,timestamptz,text,uuid,text,text,text)','EXECUTE') is distinct from true then raise exception 'ACL matrix violation: review_checkout_verifier EXECUTE observe expected true'; end if;
 if has_function_privilege('review_checkout_verifier','public.bind_research_membership_with_checkout_intent(uuid,text,text,text,text,text,timestamptz,text,text,text,text,boolean,text,text)','EXECUTE') is distinct from false then raise exception 'ACL matrix violation: review_checkout_verifier EXECUTE bind expected false'; end if;
 if has_function_privilege('review_checkout_verifier','research_checkout_guard.hold_binding_conflict(uuid,text,text)','EXECUTE') is distinct from false then raise exception 'ACL matrix violation: review_checkout_verifier EXECUTE hold expected false'; end if;
 if has_function_privilege('review_checkout_binder','public.issue_research_membership_checkout_intent(uuid,text,text,text,text,boolean,text)','EXECUTE') is distinct from false then raise exception 'ACL matrix violation: review_checkout_binder EXECUTE issue expected false'; end if;
 if has_function_privilege('review_checkout_binder','public.attach_research_membership_checkout_intent(uuid,text,text)','EXECUTE') is distinct from false then raise exception 'ACL matrix violation: review_checkout_binder EXECUTE attach expected false'; end if;
 if has_function_privilege('review_checkout_binder','public.observe_signed_research_subscription_created(text,text,text,text,text,text,boolean,timestamptz,text,uuid,text,text,text)','EXECUTE') is distinct from false then raise exception 'ACL matrix violation: review_checkout_binder EXECUTE observe expected false'; end if;
 if has_function_privilege('review_checkout_binder','public.bind_research_membership_with_checkout_intent(uuid,text,text,text,text,text,timestamptz,text,text,text,text,boolean,text,text)','EXECUTE') is distinct from true then raise exception 'ACL matrix violation: review_checkout_binder EXECUTE bind expected true'; end if;
 if has_function_privilege('review_checkout_binder','research_checkout_guard.hold_binding_conflict(uuid,text,text)','EXECUTE') is distinct from false then raise exception 'ACL matrix violation: review_checkout_binder EXECUTE hold expected false'; end if;
 if exists(select 1 from aclexplode((select proacl from pg_proc where oid='public.issue_research_membership_checkout_intent(uuid,text,text,text,text,boolean,text)'::regprocedure)) x where x.grantee=0) then raise exception 'ACL violation: PUBLIC can execute issue'; end if;
 if exists(select 1 from aclexplode((select proacl from pg_proc where oid='public.attach_research_membership_checkout_intent(uuid,text,text)'::regprocedure)) x where x.grantee=0) then raise exception 'ACL violation: PUBLIC can execute attach'; end if;
 if exists(select 1 from aclexplode((select proacl from pg_proc where oid='public.observe_signed_research_subscription_created(text,text,text,text,text,text,boolean,timestamptz,text,uuid,text,text,text)'::regprocedure)) x where x.grantee=0) then raise exception 'ACL violation: PUBLIC can execute observe'; end if;
 if exists(select 1 from aclexplode((select proacl from pg_proc where oid='public.bind_research_membership_with_checkout_intent(uuid,text,text,text,text,text,timestamptz,text,text,text,text,boolean,text,text)'::regprocedure)) x where x.grantee=0) then raise exception 'ACL violation: PUBLIC can execute bind'; end if;
 if exists(select 1 from aclexplode((select proacl from pg_proc where oid='research_checkout_guard.hold_binding_conflict(uuid,text,text)'::regprocedure)) x where x.grantee=0) then raise exception 'ACL violation: PUBLIC can execute hold'; end if;
 if exists(select 1 from pg_auth_members where roleid='review_checkout_owner'::regrole and (set_option or inherit_option)) then raise exception 'temporary owner SET/INHERIT membership still present'; end if;
 if (select count(*) from pg_policies where policyname like 'research_b5_owner_%')<>6 then raise exception 'owner policy count changed'; end if;
end $assert$;
commit;
